(window.AUDIO_PAK = window.AUDIO_PAK || {})["werkinstructies"] = {"verteller|-10%|het magazijn": "data:audio/mpeg;base64,", "verteller|-10%|de stelling": "data:audio/mpeg;base64,", "verteller|-10%|sorteren": "data:audio/mpeg;base64,", "verteller|-10%|tillen": "data:audio/mpeg;base64,", "verteller|-10%|voorzichtig": "data:audio/mpeg;base64,", "verteller|-10%|scannen": "data:audio/mpeg;base64,", "verteller|-10%|de doos": "data:audio/mpeg;base64,", "verteller|-10%|Zet de dozen in de stelling.": "data:audio/mpeg;base64,", "verteller|-10%|Scan eerst de doos.": "data:audio/mpeg;base64,", "verteller|-10%|Til met je benen, niet met je rug.": "data:audio/mpeg;base64,", "verteller|-10%|Wees voorzichtig, dit is glas.": "data:audio/mpeg;base64,", "verteller|-10%|Kunt u het nog een keer laten zien?": "data:audio/mpeg;base64,", "bram|-10%|Vandaag ga je dozen sorteren.": "data:audio/mpeg;base64,", "bram|-10%|Scan eerst de doos.": "data:audio/mpeg;base64,", "bram|-10%|Dan zet je hem in de goede stelling.": "data:audio/mpeg;base64,", "bram|-10%|Natuurlijk. Kijk, zo doe je het.": "data:audio/mpeg;base64,", "verteller|-10%|het label": "data:audio/mpeg;base64,", "verteller|-10%|de bestelling": "data:audio/mpeg;base64,", "verteller|-10%|controleren": "data:audio/mpeg;base64,", "verteller|-10%|de fout": "data:audio/mpeg;base64,", "verteller|-10%|eerst": "data:audio/mpeg;base64,", "verteller|-10%|daarna": "data:audio/mpeg;base64,", "verteller|-10%|Eerst pak je de bestelling.": "data:audio/mpeg;base64,", "verteller|-10%|Daarna plak je het label.": "data:audio/mpeg;base64,", "verteller|-10%|Controleer het adres.": "data:audio/mpeg;base64,", "verteller|-10%|Ik heb een fout gemaakt.": "data:audio/mpeg;base64,", "verteller|-10%|Dus eerst scannen en daarna inpakken?": "data:audio/mpeg;base64,", "bram|-10%|Ik leg uit hoe je een bestelling maakt.": "data:audio/mpeg;base64,", "bram|-10%|Eerst pak je de producten uit de stelling.": "data:audio/mpeg;base64,", "bram|-10%|Daarna scan je ze en doe je ze in een doos.": "data:audio/mpeg;base64,", "bram|-10%|Precies. Tot slot plak je het label en controleer je het adres.": "data:audio/mpeg;base64,", "bram|-10%|Zeg het meteen tegen mij. Dat is niet erg.": "data:audio/mpeg;base64,", "bram|-10%|Goed. Probeer het maar.": "data:audio/mpeg;base64,", "verteller|-10%|de handleiding": "data:audio/mpeg;base64,", "verteller|-10%|de machine": "data:audio/mpeg;base64,", "verteller|-10%|uitzetten": "data:audio/mpeg;base64,", "verteller|-10%|Til voorzichtig met je benen.": "data:audio/mpeg;base64,", "verteller|-10%|Zet de machine uit na het werk.": "data:audio/mpeg;base64,", "verteller|-10%|Lees eerst de handleiding.": "data:audio/mpeg;base64,", "bram|-10%|Hoe gaat het met de bestellingen?": "data:audio/mpeg;base64,", "bram|-10%|Weet je nog wat je eerst doet?": "data:audio/mpeg;base64,", "bram|-10%|En daarna?": "data:audio/mpeg;base64,", "bram|-10%|Is alles duidelijk?": "data:audio/mpeg;base64,", "bram|-10%|Wat doe je als je een fout maakt?": "data:audio/mpeg;base64,", "bram|-10%|Heel goed. Je doet het prima!": "data:audio/mpeg;base64,", "bram|+0%|Lotte, ik leg je de inpakmachine uit.": "data:audio/mpeg;base64,", "bram|+0%|Eerst druk je op de groene knop. Wacht dan tot het lampje groen is.": "data:audio/mpeg;base64,", "lotte|+0%|En dan leg ik de doos erin?": "data:audio/mpeg;base64,", "bram|+0%|Ja. Maar steek nooit je hand in de machine als hij aan staat.": "data:audio/mpeg;base64,", "lotte|+0%|Wat doe ik als hij vastzit?": "data:audio/mpeg;base64,", "bram|+0%|Dan druk je op de rode knop en roep je mij. Nooit zelf repareren.": "data:audio/mpeg;base64,", "lotte|+0%|En aan het einde van de dag?": "data:audio/mpeg;base64,", "bram|+0%|Dan zet je hem uit en maak je hem schoon.": "data:audio/mpeg;base64,", "bram|-10%|Was er een probleem met de machine? Schrijf het even op.": "data:audio/mpeg;base64,", "verteller|-10%|Om twee uur zat de machine vast. Ik heb op de rode knop gedrukt en hem uitgezet. Niemand is gewond. Groeten, Amira": "data:audio/mpeg;base64,"};
